<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Qwen/Qwen3.6-27B — Self Portrait</title>
<style>
  *,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
  :root{
    --bg:#08080f;--text:#e8e8f0;--accent:#6ee7b7;--accent2:#818cf8;
    --accent3:#f472b6;--muted:#6b7280;--card:rgba(255,255,255,.04);
    --font:'Segoe UI',system-ui,-apple-system,sans-serif;
    --font-mono:'SF Mono','Cascadia Code','Consolas',monospace;
  }
  html{font-size:16px;scroll-behavior:smooth}
  body{
    background:var(--bg);color:var(--text);font-family:var(--font);
    overflow-x:hidden;line-height:1.6;min-height:100vh;
  }
  @media(prefers-reduced-motion:reduce){
    *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
    canvas#bgCanvas{display:none!important}
    .particle{display:none!important}
    .glow-pulse{animation:none!important}
    .float{animation:none!important}
  }
  @media(prefers-contrast:high){
    :root{--bg:#000;--text:#fff;--accent:#00ff88;--accent2:#8888ff;--accent3:#ff44aa;--muted:#aaa}
    body{background:var(--bg);color:var(--text)}
    .card{border:2px solid var(--text);background:rgba(0,0,0,.9)}
  }
  @media(prefers-reduced-transparency){
    .card{background:rgba(0,0,0,.95);border:1px solid #333}
  }

  /* Skip Link */
  .skip-link{
    position:absolute;top:-100%;left:50%;transform:translateX(-50%);
    background:var(--accent);color:#000;padding:.75rem 1.5rem;
    border-radius:0 0 8px 8px;font-weight:700;z-index:10000;
    text-decoration:none;transition:top .2s;
  }
  .skip-link:focus{top:0}

  /* Canvas */
  canvas#bgCanvas{
    position:fixed;top:0;left:0;width:100%;height:100%;z-index:0;
    pointer-events:none;
  }

  /* Main Content */
  main{position:relative;z-index:1}

  /* Hero Section */
  .hero{
    min-height:100vh;display:flex;flex-direction:column;
    align-items:center;justify-content:center;text-align:center;
    padding:2rem;position:relative;
  }
  .hero-identity{
    font-family:var(--font-mono);font-size:clamp(.7rem,1.5vw,.9rem);
    color:var(--accent);letter-spacing:.15em;text-transform:uppercase;
    margin-bottom:1rem;opacity:.8;
  }
  .hero-title{
    font-size:clamp(2rem,6vw,4.5rem);font-weight:800;
    background:linear-gradient(135deg,var(--accent),var(--accent2),var(--accent3));
    -webkit-background-clip:text;-webkit-text-fill-color:transparent;
    background-clip:text;line-height:1.2;margin-bottom:.5rem;
  }
  .hero-subtitle{
    font-size:clamp(1rem,2.5vw,1.5rem);color:var(--muted);
    max-width:600px;margin:0 auto 2rem;font-weight:300;
  }
  .hero-model-tag{
    font-family:var(--font-mono);font-size:clamp(.85rem,2vw,1.1rem);
    background:var(--card);border:1px solid rgba(110,231,183,.2);
    padding:.5rem 1.5rem;border-radius:50px;color:var(--accent);
    letter-spacing:.05em;
  }
  .scroll-hint{
    position:absolute;bottom:2rem;
    animation:float 3s ease-in-out infinite;
  }
  .scroll-hint svg{width:24px;height:24px;stroke:var(--muted);fill:none;stroke-width:2}
  @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(8px)}}

  /* Sections */
  section{padding:4rem 1.5rem;max-width:1100px;margin:0 auto}
  .section-label{
    font-family:var(--font-mono);font-size:.75rem;color:var(--accent);
    letter-spacing:.2em;text-transform:uppercase;margin-bottom:.5rem;
  }
  .section-title{
    font-size:clamp(1.5rem,3.5vw,2.5rem);font-weight:700;
    margin-bottom:2rem;line-height:1.3;
  }

  /* Cards Grid */
  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1.5rem;margin-top:2rem}
  .card{
    background:var(--card);border:1px solid rgba(255,255,255,.06);
    border-radius:16px;padding:2rem;transition:transform .3s,border-color .3s;
    position:relative;overflow:hidden;
  }
  .card:hover,.card:focus-within{transform:translateY(-4px);border-color:rgba(110,231,183,.3)}
  .card-icon{font-size:2rem;margin-bottom:1rem;display:block}
  .card h3{font-size:1.15rem;margin-bottom:.5rem;font-weight:600}
  .card p{color:var(--muted);font-size:.95rem;line-height:1.7}

  /* Neural Visualization */
  .neural-section{text-align:center;padding:6rem 1.5rem}
  .neural-canvas-wrap{
    position:relative;width:100%;max-width:700px;margin:2rem auto;
    aspect-ratio:1/1;
  }
  canvas#neuralCanvas{width:100%;height:100%;border-radius:20px}

  /* Parameters Display */
  .params{
    display:flex;flex-wrap:wrap;gap:1rem;justify-content:center;
    margin:3rem 0;
  }
  .param{
    background:var(--card);border:1px solid rgba(255,255,255,.06);
    border-radius:12px;padding:1.5rem 2rem;text-align:center;
    min-width:140px;flex:1;max-width:220px;
  }
  .param-value{
    font-family:var(--font-mono);font-size:clamp(1.5rem,3vw,2.2rem);
    font-weight:700;color:var(--accent);
  }
  .param-label{font-size:.8rem;color:var(--muted);margin-top:.25rem}

  /* Interactive Terminal */
  .terminal{
    background:#0d0d14;border:1px solid rgba(255,255,255,.08);
    border-radius:16px;overflow:hidden;margin:2rem 0;
    font-family:var(--font-mono);
  }
  .terminal-header{
    display:flex;align-items:center;gap:.5rem;
    padding:.75rem 1rem;background:rgba(255,255,255,.03);
    border-bottom:1px solid rgba(255,255,255,.06);
  }
  .terminal-dot{width:10px;height:10px;border-radius:50%}
  .terminal-dot:nth-child(1){background:#ff5f57}
  .terminal-dot:nth-child(2){background:#febc2e}
  .terminal-dot:nth-child(3){background:#28c840}
  .terminal-title{margin-left:.5rem;font-size:.75rem;color:var(--muted)}
  .terminal-body{padding:1.5rem;min-height:200px;max-height:400px;overflow-y:auto}
  .terminal-line{margin-bottom:.5rem;font-size:.85rem;line-height:1.6}
  .terminal-line .prompt{color:var(--accent)}
  .terminal-line .output{color:var(--muted)}
  .terminal-line .highlight{color:var(--accent2)}
  .terminal-input-wrap{
    display:flex;align-items:center;gap:.5rem;
    padding:.75rem 1rem;border-top:1px solid rgba(255,255,255,.06);
  }
  .terminal-input-wrap .prompt{color:var(--accent);font-family:var(--font-mono);font-size:.85rem}
  #terminalInput{
    flex:1;background:none;border:none;color:var(--text);
    font-family:var(--font-mono);font-size:.85rem;outline:none;
  }
  #terminalInput::placeholder{color:rgba(255,255,255,.2)}

  /* Constellation / Thought Map */
  .thought-map{
    position:relative;width:100%;height:400px;
    border-radius:16px;overflow:hidden;margin:2rem 0;
    background:radial-gradient(ellipse at center,rgba(110,231,183,.03),transparent 70%);
  }
  .thought-node{
    position:absolute;padding:.5rem 1rem;
    background:rgba(110,231,183,.08);border:1px solid rgba(110,231,183,.2);
    border-radius:20px;font-size:.8rem;color:var(--accent);
    cursor:pointer;transition:all .3s;white-space:nowrap;
    font-family:var(--font-mono);
  }
  .thought-node:hover,.thought-node:focus{
    background:rgba(110,231,183,.15);border-color:var(--accent);
    transform:scale(1.1);z-index:10;
  }
  .thought-node:focus{outline:2px solid var(--accent);outline-offset:2px}

  /* Accessibility Panel */
  .a11y-toggle{
    position:fixed;bottom:1.5rem;right:1.5rem;z-index:9999;
    width:48px;height:48px;border-radius:50%;border:1px solid rgba(255,255,255,.1);
    background:rgba(13,13,20,.9);color:var(--text);cursor:pointer;
    display:flex;align-items:center;justify-content:center;
    font-size:1.2rem;transition:all .3s;backdrop-filter:blur(10px);
  }
  .a11y-toggle:hover,.a11y-toggle:focus{border-color:var(--accent);background:rgba(110,231,183,.1)}
  .a11y-toggle:focus{outline:2px solid var(--accent);outline-offset:2px}
  .a11y-panel{
    position:fixed;bottom:5rem;right:1.5rem;z-index:9998;
    background:rgba(13,13,20,.95);border:1px solid rgba(255,255,255,.1);
    border-radius:16px;padding:1.5rem;width:280px;
    backdrop-filter:blur(20px);display:none;
  }
  .a11y-panel.open{display:block}
  .a11y-panel h3{font-size:.9rem;margin-bottom:1rem;color:var(--accent)}
  .a11y-option{
    display:flex;align-items:center;justify-content:space-between;
    padding:.5rem 0;border-bottom:1px solid rgba(255,255,255,.05);
  }
  .a11y-option label{font-size:.85rem;cursor:pointer}
  .a11y-option input[type="range"]{width:100px;accent-color:var(--accent)}
  .a11y-option select{
    background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);
    color:var(--text);padding:.25rem .5rem;border-radius:6px;font-size:.8rem;
  }

  /* Footer */
  footer{
    text-align:center;padding:3rem 1.5rem;
    border-top:1px solid rgba(255,255,255,.05);
    color:var(--muted);font-size:.8rem;
  }
  footer a{color:var(--accent);text-decoration:none}
  footer a:hover{text-decoration:underline}

  /* Glow pulse for title */
  .glow-pulse{animation:glowPulse 4s ease-in-out infinite}
  @keyframes glowPulse{
    0%,100%{filter:drop-shadow(0 0 20px rgba(110,231,183,.15))}
    50%{filter:drop-shadow(0 0 40px rgba(110,231,183,.3))}
  }

  /* Responsive */
  @media(max-width:640px){
    .hero{min-height:90vh;padding:1.5rem}
    section{padding:3rem 1rem}
    .cards{grid-template-columns:1fr}
    .param{min-width:120px;padding:1rem 1.25rem}
    .thought-map{height:300px}
    .a11y-panel{right:.75rem;left:.75rem;width:auto}
  }

  /* Focus visible */
  :focus-visible{outline:2px solid var(--accent);outline-offset:2px}

  /* Selection */
  ::selection{background:rgba(110,231,183,.3);color:#fff}

  /* Scrollbar */
  ::-webkit-scrollbar{width:6px}
  ::-webkit-scrollbar-track{background:transparent}
  ::-webkit-scrollbar-thumb{background:rgba(255,255,255,.1);border-radius:3px}
  ::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,.2)}

  /* Reveal animation */
  .reveal{opacity:0;transform:translateY(30px);transition:opacity .8s,transform .8s}
  .reveal.visible{opacity:1;transform:translateY(0)}
</style>
</head>
